import {EVM,SOL,FEE_TOPICS,canonical,safeJSON,blockscoutRows,decodeFeeLogs,parseSolanaTransaction} from './ledger.mjs';
const delay=ms=>new Promise(r=>setTimeout(r,ms));
let nextBlockscoutRequest=0;
export async function request(url,options={},signal){for(let i=0;i<4;i++){if(signal?.aborted)throw Error('已暂停');const timeout=AbortSignal.timeout(30000);let response;try{response=await fetch(url,{...options,signal:signal?AbortSignal.any([signal,timeout]):timeout,cache:'no-store',referrerPolicy:'no-referrer'})}catch{if(signal?.aborted)throw Error('已暂停');if(i===3)throw Error('网络连接失败或超时；数据尚未完整');await delay(800*(i+1));continue}let detail='';if(!response.ok&&String(url).startsWith('/api/')){try{detail=(await response.clone().json()).message||''}catch{}}if(response.status===429||response.status>=500){if(i===3)throw Error(detail||`数据源限流或暂不可用（${response.status}），可稍后继续`);await delay(Math.min(15000,Number(response.headers.get('retry-after')||i+1)*1500));continue}if(!response.ok)throw Error(detail||(response.status===401||response.status===403?'API Key 无效、额度不足或尚未开通此接口':`数据源返回 HTTP ${response.status}`));const text=await response.text();let data;try{data=safeJSON(text)}catch{throw Error('数据源返回了非 JSON 响应')}if(data.error){let msg=String(data.error.message||data.error).slice(0,300);const u=new URL(url, 'http://localhost');for(const secret of [...u.searchParams.values(),u.pathname.split('/').at(-1)])if(secret&&secret.length>8)msg=msg.split(secret).join('[已隐藏]');throw Error(`数据源错误 ${data.error.code||''}：${msg}`)}return data}throw Error('查询失败')}
export async function bs(chain,path,key,params={},signal){if(!key)throw Error('请先填写 Blockscout API Key');const at=Math.max(Date.now(),nextBlockscoutRequest);nextBlockscoutRequest=at+260;await delay(at-Date.now());return request('/api/blockscout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({chain,path,key,params})},signal)}
async function pages(chain,path,key,signal){let cursor=null,items=[],seen=new Set;do{const data=await bs(chain,path,key,cursor||{},signal);if(!Array.isArray(data.items))throw Error('分页响应缺少 items');items.push(...data.items);cursor=data.next_page_params;const c=JSON.stringify(cursor);if(cursor&&seen.has(c))throw Error('分页游标重复，停止以免遗漏或重复计算');seen.add(c)}while(cursor);return items}
export async function scanEVM(chain,key,routers,onPage,onProgress,signal,start={}){
 let records=[];
 for(const stream of ['transactions','internal-transactions','token-transfers']){
  const saved={...start[stream]};if(saved.complete)continue;
  let cursor=saved.cursor||null,highBlock=saved.highBlock??null,seen=new Set;
  do{
   onProgress(`${chain.name} · ${saved.stopBlock!=null?'增量':'历史'} · ${stream}`);
   const data=await bs(chain.id,`addresses/${EVM}/${stream}`,key,cursor||{},signal);
   if(!Array.isArray(data.items))throw Error('地址历史响应格式不正确');
   const height=x=>Number(x.block_number??x.block);
   if(saved.stopBlock==null&&saved.anchors?.length){const anchor=data.items.find(x=>saved.anchors.includes(x.transaction_hash||x.hash)&&Number.isSafeInteger(height(x)));if(anchor)saved.stopBlock=Math.max(0,height(anchor)-64)}
   const heights=data.items.map(height).filter(Number.isSafeInteger);
   if(heights.length)highBlock=Math.max(highBlock??0,...heights);
   const reached=saved.stopBlock!=null&&data.items.some(x=>Number.isSafeInteger(height(x))&&height(x)<saved.stopBlock);
   const items=data.items.filter(x=>saved.stopBlock==null||!Number.isSafeInteger(height(x))||height(x)>=saved.stopBlock);
   const rows=blockscoutRows(items,stream,chain);records.push(...rows);
   cursor=reached?null:data.next_page_params;
   await onPage(rows,{stream,cursor,complete:!cursor,highBlock,stopBlock:saved.stopBlock??null,anchors:saved.anchors||[]});
   const c=JSON.stringify(cursor);if(cursor&&seen.has(c))throw Error('分页未前进，历史尚未完整');seen.add(c);
  }while(cursor);
 }
 return records;
}
export async function inspectEVM(chain,hash,key,routers,rows,signal){const tx=await bs(chain.id,`transactions/${hash}`,key,{},signal);if(!tx.hash)throw Error('缺少交易详情');if(!['ok','success'].includes(tx.status))return {replace:rows.map(r=>({...r,kind:'ignore',evidence:'失败或未成功确认的交易，不计入'})),fees:[]};tx.from.is_contract ??= true;const incoming=rows.some(r=>r.direction==='in'),logs=incoming?await pages(chain.id,`transactions/${hash}/logs`,key,signal):[];const tokenMeta={};for(const r of rows)tokenMeta[r.asset]={symbol:r.symbol,decimals:r.decimals};for(const l of logs){if(!l.data||![194,258].includes(l.data.length))continue;const token='0x'+l.data.slice(26,66).toLowerCase();if(!['0xeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee'].includes(token)&&!tokenMeta[token]&&l.topics?.some(t=>FEE_TOPICS.includes(t))){const m=await bs(chain.id,`tokens/${token}`,key,{},signal);tokenMeta[token]=m}}
const fees=decodeFeeLogs(logs,chain,tx,tokenMeta,routers[chain.id]||[]);const replace=rows.map(r=>{const next={...r,txSender:canonical(chain.id,tx.from?.hash)};delete next.inspectionError;if(next.supersededBy&&!next.reviewed){next.kind='pending';delete next.supersededBy}if(r.direction==='in'&&!r.trader)next.trader=canonical(chain.id,tx.from?.hash);if(r.stream==='internal-transactions'&&r.asset==='native'&&r.from===canonical(chain.id,tx.from?.hash)&&r.to===canonical(chain.id,tx.to?.hash)&&r.raw===String(tx.value)&&Number(r.id.split(':').at(-1))===0){next.kind='ignore';next.evidence='顶层原生币转账重复表示，已去重'}return next});for(const asset of new Set(fees.map(f=>f.asset))){const rs=replace.filter(r=>!r.feeEvent&&r.direction==='in'&&r.asset===asset&&r.kind!=='ignore');const fs=fees.filter(f=>f.asset===asset);if(rs.reduce((n,r)=>n+BigInt(r.raw),0n)===fs.reduce((n,f)=>n+BigInt(f.raw),0n)){for(const f of fs)f.receiptMatched=true;for(const r of rs){r.kind='ignore';r.supersededBy=fs.map(f=>f.id);r.evidence='已由同笔返佣事件计入，转账记录不重复计账'}}else{for(const f of fs){f.kind='ignore';f.evidence='返佣事件金额与实际转入不一致，本事件不计账；请核对实际转账记录'}}}return {replace,fees}}
export async function scanSolana(key,onPage,onProgress,signal,start={}){if(start.complete)return;if(!key)throw Error('请先填写 Helius API Key');let before=start.cursor,headSignature=start.headSignature||null,seen=new Set;do{onProgress('Solana · SOL / SPL / Token-2022 历史（含代币账户）');const u=new URL(`https://api.helius.xyz/v0/addresses/${SOL}/transactions`);u.searchParams.set('api-key',key);u.searchParams.set('limit','10');u.searchParams.set('token-accounts','balanceChanged');u.searchParams.set('commitment','finalized');if(before)u.searchParams.set('before-signature',before);const data=await request(u,{},signal);if(!Array.isArray(data))throw Error('Helius 历史格式错误');if(!before&&data.length)headSignature=data[0].signature;const stop=start.until?data.findIndex(x=>x.signature===start.until):-1;const fresh=stop<0?data:data.slice(0,stop);const rows=[];for(const item of fresh){if(item.transactionError)continue;const rpc=await request(`https://mainnet.helius-rpc.com/?api-key=${encodeURIComponent(key)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'getTransaction',params:[item.signature,{encoding:'jsonParsed',commitment:'finalized',maxSupportedTransactionVersion:0}]})},signal);const parsed=parseSolanaTransaction(rpc.result,item.signature);for(const r of parsed){r.suggestedTrader=item.feePayer;r.source=item.source||'UNKNOWN'}rows.push(...parsed);await delay(120)}before=data.length?data.at(-1).signature:null;await onPage(rows,{stream:'solana',cursor:before,complete:data.length===0||stop>=0,headSignature,until:start.until||null});if(data.length===0||stop>=0)break;if(seen.has(before))throw Error('Solana 分页未前进');seen.add(before)}while(before)}
